import{describe,it,expect}from"vitest";import{CBI_HISTORY_TIMELINE,CBI_FORMATION_INFO,CBI_ORGANIZATION_HIERARCHY,CBI_DIRECTOR_SELECTION,CBI_DIVISIONS,CBI_POWERS_FRAMEWORK,CBI_FAMOUS_INVESTIGATIONS,CBI_FAQS,CBI_INFOGRAPHICS_DATA,filterCases,toggleFaqState,getCbiKnowledgeStats}from"../../frontend/cbi-knowledge-center/cbi-knowledge-center.js";describe("CBI History Timeline Integrity",()=>{it("contains at least 6 historical milestones starting from 1941 SPE",()=>{expect(CBI_HISTORY_TIMELINE.length).toBeGreaterThanOrEqual(6),expect(CBI_HISTORY_TIMELINE[0].year).toBe("1941")}),it("every milestone has year, title, era, summary, and details fields",()=>{CBI_HISTORY_TIMELINE.forEach((e,t)=>{expect(e,`Milestone at index ${t} missing year`).toHaveProperty("year"),expect(e,`Milestone at index ${t} missing title`).toHaveProperty("title"),expect(e,`Milestone at index ${t} missing era`).toHaveProperty("era"),expect(e,`Milestone at index ${t} missing summary`).toHaveProperty("summary"),expect(e,`Milestone at index ${t} missing details`).toHaveProperty("details"),expect(typeof e.title).toBe("string"),expect(e.title.trim().length).toBeGreaterThan(0),expect(typeof e.summary).toBe("string"),expect(e.summary.trim().length).toBeGreaterThan(0)})})}),describe("CBI Divisions & Organization Dataset Integrity",()=>{it("defines 7 specialized operational divisions including ACD, EOD, and Interpol NCB",()=>{expect(CBI_DIVISIONS.length).toBe(7);const e=CBI_DIVISIONS.map(e=>e.id);expect(e).toContain("acd"),expect(e).toContain("eod"),expect(e).toContain("scd"),expect(e).toContain("dop"),expect(e).toContain("cfsl"),expect(e).toContain("pc"),expect(e).toContain("std")}),it("defines organizational hierarchy ranks from Director down to Field Investigating Officers",()=>{expect(CBI_ORGANIZATION_HIERARCHY.length).toBeGreaterThanOrEqual(5),expect(CBI_ORGANIZATION_HIERARCHY[0].rank).toBe("Director, CBI")})}),describe("CBI Director Selection Committee & Legal Powers",()=>{it("correctly specifies the High-Powered Selection Committee (PM, LoP/Single Largest Party Leader, CJI)",()=>{const e=CBI_DIRECTOR_SELECTION.committeeMembers;expect(e.length).toBe(3);const t=e.map(e=>e.title);expect(t.some(e=>e.includes("Prime Minister"))).toBe(!0),expect(t.some(e=>e.includes("Leader of Opposition"))).toBe(!0),expect(t.some(e=>e.includes("Chief Justice of India"))).toBe(!0)}),it("defines Section 6 DSPE Act General Consent, Specific Consent, and Judicial Mandate powers",()=>{const e=CBI_POWERS_FRAMEWORK.jurisdictionTypes;expect(e.length).toBe(4);const t=e.map(e=>e.title);expect(t.some(e=>e.includes("General Consent"))).toBe(!0),expect(t.some(e=>e.includes("Specific Consent"))).toBe(!0),expect(t.some(e=>e.includes("Judicial Mandate"))).toBe(!0)})}),describe("CBI Famous Investigations & FAQs Dataset",()=>{it("contains famous landmark investigations with neutral legal framing",()=>{expect(CBI_FAMOUS_INVESTIGATIONS.length).toBeGreaterThanOrEqual(5),CBI_FAMOUS_INVESTIGATIONS.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("category"),expect(e).toHaveProperty("summary"),expect(e).toHaveProperty("details")})}),it("contains comprehensive citizen FAQs addressing DSPE Act and Interpol",()=>{expect(CBI_FAQS.length).toBeGreaterThanOrEqual(5),CBI_FAQS.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("question"),expect(e).toHaveProperty("answer"),expect(e.question.endsWith("?")).toBe(!0)})})}),describe("CBI Helper & Filter Logic",()=>{it("filters cases by category correctly",()=>{const e=filterCases(CBI_FAMOUS_INVESTIGATIONS,"Special Crimes","");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.category).toBe("Special Crimes"));const t=filterCases(CBI_FAMOUS_INVESTIGATIONS,"Economic Offences","");expect(t.length).toBeGreaterThan(0),t.forEach(e=>expect(e.category).toBe("Economic Offences"))}),it("filters cases by keyword search query",()=>{const e=filterCases(CBI_FAMOUS_INVESTIGATIONS,"all","Satyam");expect(e.length).toBe(1),expect(e[0].title).toContain("Satyam")}),it("toggles FAQ expanded state correctly without mutating original array",()=>{const e=CBI_FAQS.map(e=>({...e,expanded:!1})),t=toggleFaqState(e,"faq-1");expect(t[0].expanded).toBe(!0),expect(e[0].expanded).toBe(!1)}),it("returns valid CBI knowledge statistics",()=>{const e=getCbiKnowledgeStats();expect(e.totalDivisions).toBe(7),expect(e.timelineMilestones).toBeGreaterThanOrEqual(6),expect(e.interpolMemberCountries).toBe(195)})});